// Package rolecheck inventories SQL executed by the connected indexer runtime role.
package rolecheck

import (
	"regexp"
	"sort"
	"strings"
)

// Statement describes one connected-form database statement and its authority.
type Statement struct {
	ID        string
	Package   string
	File      string
	Function  string
	Kind      string
	Tables    []string
	Sequences []string
	Functions []string
	Columns   []string
	Role      string
	SQL       string
}

func statementKind(sql string) string {
	fields := strings.Fields(strings.TrimSpace(sql))
	if len(fields) == 0 {
		return ""
	}
	return strings.ToUpper(fields[0])
}

var (
	statementRelationPattern = regexp.MustCompile(`(?i)\b(?:FROM|JOIN|INTO|UPDATE|USING)\s+([a-z_][a-z0-9_]*\.[a-z_][a-z0-9_]*)`)
	statementFunctionPattern = regexp.MustCompile(`(?i)\b([a-z_][a-z0-9_]*\.[a-z_][a-z0-9_]*)\s*\(`)
	statementColumnPattern   = regexp.MustCompile(`\b[a-z_][a-z0-9_]*\.([a-z_][a-z0-9_]*)\b`)
	statementSequencePattern = regexp.MustCompile(`(?i)\b(?:nextval|currval|setval)\s*\(\s*'([^']+)'`)
)

func init() {
	for i := range RuntimeRoleStatements {
		statement := &RuntimeRoleStatements[i]
		statement.Tables = sortedMatches(statementRelationPattern, statement.SQL)
		statement.Functions = sortedMatches(statementFunctionPattern, statement.SQL)
		statement.Columns = sortedMatches(statementColumnPattern, statement.SQL)
		statement.Sequences = sortedMatches(statementSequencePattern, statement.SQL)
	}
}

func sortedMatches(pattern *regexp.Regexp, sql string) []string {
	seen := map[string]bool{}
	for _, match := range pattern.FindAllStringSubmatch(sql, -1) {
		if len(match) > 1 {
			seen[match[1]] = true
		}
	}
	values := make([]string, 0, len(seen))
	for value := range seen {
		values = append(values, value)
	}
	sort.Strings(values)
	return values
}

